impl Solution{pub fn find_strobogrammatic(n:i32)->Vec<String>{fn f(s:&mut Vec<u8>,l:i32,r:i32,o:&mut Vec<String>){let p=[(b'0',b'0'),(b'1',b'1'),(b'6',b'9'),(b'8',b'8'),(b'9',b'6')];if l>r{o.push(String::from_utf8(s.clone()).unwrap());return}for &(a,b)in&p{if l==0&&r>0&&a==b'0'{continue}if l==r&&a!=b{continue}s[l as usize]=a;s[r as usize]=b;f(s,l+1,r-1,o)}}let mut o=vec![];let mut s=vec![b' ';n as usize];f(&mut s,0,n-1,&mut o);o}}
